import{z as B,x as d,o as E,c as p,q as n,j as i,D as t,d as r,s as l,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"关键路径","description":"","frontmatter":{"title":"关键路径","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/critical-path.md","filePath":"cs/critical-path.md","lastUpdated":1791063341000}'),A={name:"cs/critical-path.md"};function c(D,a,h,m,_,u){const s=d("Mermaid");return E(),p("div",null,[a[2]||(a[2]=n('<h1 id="关键路径" tabindex="-1">关键路径 <a class="header-anchor" href="#关键路径" aria-label="Permalink to &quot;关键路径&quot;">​</a></h1><div class="epigraph"><p>电路的传播延迟不是「平均看起来多久」，而是输入到输出所有拓扑路径里最慢的那一条。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p>上一课<a href="/cs/gate-delay">组合逻辑时延</a>给每个门贴了 \\(t_{pd}\\) 与 \\(t_{cd}\\)。本课不重定义这两个量，也不从静态时序工具的 SDC 另起。缺口是：网表有许多输入-输出路径，后课周期、加法器选型、ALU 深度，要比的是<strong>那一条最坏和</strong>，不是某一条典型路径。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单位延迟模型下，路径延迟是沿途门 \\(t_{pd}\\) 之和。电路 \\(t_{pd}\\) 取最大；那条路径叫关键路径。缺口因此不是新的门，而是：优化必须动这条路径——缩短非关键路径不提高时钟。假路径（功能上走不到的组合）可以标掉，本课承认存在，不把例外表写完。</p><p>后课<a href="/cs/mux-select">MUX</a>、CLA、单周期 <code>lw</code>，都先找出哪一段串联最长。</p><h3 id="关键路径不是「门最多的那条」" tabindex="-1">关键路径不是「门最多的那条」 <a class="header-anchor" href="#关键路径不是「门最多的那条」" aria-label="Permalink to &quot;关键路径不是「门最多的那条」&quot;">​</a></h3><p>扇入、扇出、线负载改写每级延迟。门数少但每级很重，可以比门数多的浅路径更慢。把「级数」与「延迟」当成同一数字，超前进位的分组理由会说不清。</p><p><span class="marginnote">Harris 用路径延迟比较实现。Patterson/Hennessy 把 CPU 周期钉在最长指令的组合路径上。本课仍无时钟：关键路径是组合云的直径。</span></p><p><span class="marginnote">直觉类比：把电路想成一串红绿灯——整段路的通行时间由最长的红灯串决定；去优化一条没几个红灯的岔路，整段通行时间一秒也不会变快。关键路径就是那串最长的红灯。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从每个输入到每个输出做加权最长路（门延迟为边权）。输出再作为下一块输入时，把块当作超节点，块间再比。污染路径取最短，给后课保持时间用，不是本课的「关键」。</p>',12)),(E(),i(o,null,{default:t(()=>[l(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20GATES%5B%22%E5%B8%A6%20t_pd%20%E7%9A%84%E9%97%A8%E7%BD%91%22%5D%20--%3E%20PATHS%5B%22%E5%85%A8%E4%BD%93%E8%BE%93%E5%85%A5%E5%88%B0%E8%BE%93%E5%87%BA%E8%B7%AF%E5%BE%84%22%5D%0A%20%20PATHS%20--%3E%20CRIT%5B%22%E5%BB%B6%E8%BF%9F%E5%92%8C%E6%9C%80%E5%A4%A7%E8%80%85%22%5D%0A%20%20CRIT%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AMUX%20%E7%AD%89%E5%91%BD%E5%90%8D%E5%9D%97%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"数字实例：16 位行波加法器的进位要串过 16 级门，每级 20 ps 就是 320 ps；CLA 把进位链拆成约 4 层的 g/p 树，同样每级 20 ps 只需约 80 ps——位数越多，拆链的收益越大。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"行波加法的关键路径沿进位链，故 \\(t_{pd}=\\Theta(n)\\)。CLA 把这条链拆成 \\(g,p\\) 树，关键路径改走树高。后课单周期把「取指 + 译码 + ALU + 访存 + 写回 MUX」串成一条更长的关键路径；流水线再把它切开。本课只给「找最长」这一格。",-1)),(E(),i(o,null,{default:t(()=>[l(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20RIP%5B%22%E8%A1%8C%E6%B3%A2%E5%8A%A0%E6%B3%95%3A%20%E8%BF%9B%E4%BD%8D%E9%80%90%E7%BA%A7%E4%BC%A0%E9%80%92%22%5D%20--%3E%20CHAIN%5B%22%E5%85%B3%E9%94%AE%E8%B7%AF%E5%BE%84%20%3D%20n%20%E7%BA%A7%E8%BF%9B%E4%BD%8D%E9%93%BE%22%5D%0A%20%20CHAIN%20--%3E%20LIN%5B%22%E5%BB%B6%E8%BF%9F%E9%9A%8F%E4%BD%8D%E6%95%B0%E7%BA%BF%E6%80%A7%E5%A2%9E%E9%95%BF%22%5D%0A%20%20CLA%5B%22CLA%3A%20g%2Fp%20%E6%8F%90%E5%89%8D%E5%B9%B6%E8%A1%8C%E7%AE%97%E8%BF%9B%E4%BD%8D%22%5D%20--%3E%20TREE%5B%22%E5%85%B3%E9%94%AE%E8%B7%AF%E5%BE%84%E6%94%B9%E8%B5%B0%E6%A0%91%E9%AB%98%22%5D%0A%20%20TREE%20--%3E%20LOG%5B%22%E5%BB%B6%E8%BF%9F%E9%9A%8F%E4%BD%8D%E6%95%B0%E5%AF%B9%E6%95%B0%E5%A2%9E%E9%95%BF%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">常见误区：门数少不等于快。一条 3 级但每级很重的路径，可以比 6 级的浅路径更慢——比的是各级延迟之和，不是级数；把两把尺子混为一谈，超前进位为什么按组拆链就讲不清了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不跑 STA 工具、不建 RC 抽取。不把异步环振的周期当关键路径——那不是同步约束。多周期路径（有意两拍才采样）后课才出现。</p><p>后课默认：比较两个组合实现，先比关键路径；后课数据通路的周期下界来自这条路径加建立时间。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>关键路径是最坏 \\(t_{pd}\\) 之和，决定组合块有多慢。</li><li>优化非关键路径不提高时钟。</li><li>门数与延迟不是同一尺子。</li><li>出处：Harris and Harris；Patterson and Hennessy, COD (RISC-V)。</li></ul>',6))])}const f=B(A,[["render",c]]);export{T as __pageData,f as default};
